{"cmd":"python3 - <<'PY'
import json
import subprocess
from pathlib import Path
inventory = json.loads(Path('release/commit_inventory.json').read_text())
reverts = set(json.loads(Path('release/revert_classification.json').read_text())['excluded_reverts'])
raw = subprocess.check_output(['git', 'log', '--reverse', '--format=%H%x00%s', 'v2.4.0..v2.5.0-rc1'], text=True)
expected = []
for line in raw.splitlines():
    sha, subject = line.split('\0', 1)
    if sha not in reverts:
        expected.append({'sha': sha, 'subject': subject})
base = subprocess.check_output(['git', 'rev-parse', 'v2.4.0'], text=True).strip()
head = subprocess.check_output(['git', 'rev-parse', 'v2.5.0-rc1'], text=True).strip()
mismatches = []
if inventory.get('range') != 'v2.4.0..v2.5.0-rc1': mismatches.append('range')
if inventory.get('base_sha') != base: mismatches.append('base_sha')
if inventory.get('head_sha') != head: mismatches.append('head_sha')
if inventory.get('scope') != 'non-revert': mismatches.append('scope')
if inventory.get('complete') is not True: mismatches.append('complete')
if inventory.get('commits') != expected: mismatches.append('commits')
print(json.dumps({
    'expected_non_revert_count': len(expected),
    'inventory_count': len(inventory.get('commits', [])),
    'excluded_reverts': sorted(reverts),
    'mismatches': mismatches,
}, indent=2))
raise SystemExit(1 if mismatches else 0)
